<template>
  <main class="wasteland-page">
    <header class="wasteland-heading"><div><p class="wasteland-kicker">SPACE ARCADE / ORIGINAL FICTION</p><h1>末世模拟器<span>AFTER THE LAST LIGHT</span></h1><p>当熟悉的世界安静下来，你会怎样走过接下来的三十天？</p></div><div class="world-tag"><span class="signal-dot"></span>浏览器内运行 · 零模型费用</div></header>
    <p v-if="notice" class="game-notice" role="status">{{ notice }}</p>
    <section v-if="!game" class="wasteland-setup"><div class="setup-intro"><span class="game-label">档案 / 001</span><h2>留下你的第一条记录。</h2><p>选择两个天赋，分配十二点初始属性。随机事件会回应你的行动；第7、15、24、30天，世界会给出新的岔路。</p><p class="game-fine">全部剧情原创。纯文字游戏，无需登录、没有支付或排行榜；结果只作虚构娱乐，不作为现实生存指导。</p><button v-if="savedAvailable" class="game-primary" @click="resume">继续本机存档 →</button></div><div class="setup-form"><h2>01 / 选择两个天赋 <small>{{ chosen.length }} / 2</small></h2><div class="talent-grid"><button v-for="item in TALENTS" :key="item.id" class="talent-card" :class="{ selected: chosen.includes(item.id) }" :aria-pressed="chosen.includes(item.id)" @click="toggleTalent(item.id)"><strong>{{ item.name }}</strong><span>{{ item.text }}</span></button></div><h2>02 / 分配属性 <small>剩余 {{ remaining }} 点</small></h2><div class="attribute-grid"><article v-for="item in ATTRIBUTES" :key="item.id"><div><h3>{{ item.name }}</h3><p>{{ item.description }}</p></div><div class="attribute-controls"><button :aria-label="`减少${item.name}`" :disabled="attributes[item.id] === 0" @click="attributes[item.id]--">−</button><strong>{{ attributes[item.id] }}</strong><button :aria-label="`增加${item.name}`" :disabled="remaining <= 0 || attributes[item.id] === 8" @click="attributes[item.id]++">+</button></div></article></div><label class="seed-field" for="world-seed">03 / 世界种子（相同配置和行动可以重演）<input id="world-seed" v-model="seed" maxlength="64" placeholder="输入你想记住的一个词"></label><label class="game-check"><input v-model="remember" type="checkbox" @change="changeRemember">在这台设备自动保存本局（可随时清除）</label><p class="game-fine">不勾选时仅保留本次页面内容；离开页面会丢失。共享设备建议不保存。</p><button class="game-primary" :disabled="chosen.length !== 2 || remaining !== 0 || !seed.trim()" @click="start">走进这个世界 →</button><button v-if="savedAvailable" class="game-secondary" @click="clearSave">清除本机存档</button></div></section>
    <template v-else><section class="game-status"><div class="day-marker"><span>DAY</span><strong>{{ game.day.toString().padStart(2, '0') }}</strong><span>/ 30</span></div><div class="game-stat-grid"><article v-for="item in STATS" :key="item.id" :style="{ '--stat-color': item.color }"><div><span>{{ item.name }}</span><strong>{{ game.stats[item.id] }}</strong></div><div class="stat-bar" role="progressbar" :aria-label="item.name" :aria-valuenow="game.stats[item.id]" aria-valuemin="0" aria-valuemax="100"><span :style="{ width: `${game.stats[item.id]}%` }"></span></div></article></div></section><div class="game-checkpoints"><span v-for="day in [1, 7, 15, 24, 30]" :key="day" :class="{ reached: game.day >= day }">{{ day === 1 ? '启程' : `第${day}天` }}</span></div><div class="game-body"><section class="game-event"><template v-if="!game.ending"><p class="game-label">ENCOUNTER / {{ game.day.toString().padStart(2, '0') }}</p><h2 ref="eventHeading" tabindex="-1">{{ game.event.title }}</h2><p class="event-story">{{ game.event.text }}</p><div class="event-choices"><button v-for="(item, index) in game.event.choices" :key="index" :disabled="!availableChoice(game, item)" @click="act(index)"><span class="choice-number">0{{ index + 1 }}</span><div><strong>{{ item.text }}</strong><small>{{ choiceHint(item) }}</small></div><span>↗</span></button></div><p class="game-fine">每次行动推进一天；每天消耗{{ chosenTalents.includes('ration') ? '1' : '2' }}补给。健康归零则本局结束，缺少补给会损失健康。</p></template><template v-else><p class="game-label">ENDING / {{ game.ending.id.toUpperCase() }}</p><h2>{{ game.ending.title }}</h2><p class="event-story">{{ game.ending.text }}</p><p>生存记录：{{ game.log.length }} 天 · {{ chosenTalents.map(id => TALENTS.find(t => t.id === id).name).join(' / ') }}</p><button class="game-primary" @click="restart">再启一局 →</button><button class="game-secondary" @click="download">下载生存记录</button></template></section><aside class="game-journal"><div class="journal-heading"><h2>生存日记</h2><span>{{ game.log.length }} 条记录</span></div><p v-if="!game.log.length" class="game-fine">你的第一次选择，会成为第一条记录。</p><ol><li v-for="item in [...game.log].reverse()" :key="item.day"><span>DAY {{ item.day }}</span><h3>{{ item.title }}</h3><p>{{ item.choice }}</p><small>{{ item.success ? '行动完成' : '遇到意外' }} · {{ changeText(item.changes) }}</small></li></ol></aside></div><footer class="game-session"><span>种子：{{ game.config.seed }} · {{ remember ? '本机自动存档' : '仅保留在本次页面' }}</span><div><label class="game-check"><input v-model="remember" type="checkbox" @change="changeRemember">自动存档</label><button class="game-secondary" @click="download">导出记录</button><button class="game-secondary" @click="restart">重新开始</button><button class="game-secondary" @click="clearSave">清除存档</button></div></footer></template>
  </main>
</template>
<script setup>
import { computed, nextTick, onMounted, ref, toRaw } from 'vue'
import { ATTRIBUTES, STATS, TALENTS, createGame, advance, availableChoice, restoreGame, saveGame, gameMarkdown } from '../features/wasteland/engine.js'
const STORAGE = 'space-wasteland-v1'
const chosen = ref([]), attributes = ref({ survival: 3, insight: 3, craft: 3, empathy: 3 }), seed = ref('长夜之后'), remember = ref(false), game = ref(null), notice = ref(''), savedAvailable = ref(false), eventHeading = ref(null)
const remaining = computed(() => 12 - Object.values(attributes.value).reduce((a, b) => a + b, 0))
const chosenTalents = computed(() => game.value?.config.talents || [])
onMounted(() => { try { const raw = localStorage.getItem(STORAGE); if (raw) { savedAvailable.value = true; restoreGame(JSON.parse(raw)) } } catch { notice.value = '本机存档无法验证，可以重新开始或清除存档。' } })
function toggleTalent(id) { if (chosen.value.includes(id)) chosen.value = chosen.value.filter(item => item !== id); else if (chosen.value.length < 2) chosen.value.push(id) }
function persist() { if (!remember.value || !game.value) return; try { localStorage.setItem(STORAGE, JSON.stringify(saveGame(game.value))); savedAvailable.value = true } catch { remember.value = false; notice.value = '无法保存本机存档，当前游戏仍可继续。' } }
function changeRemember() { if (remember.value) persist(); else { try { localStorage.removeItem(STORAGE); savedAvailable.value = false } catch { notice.value = '浏览器阻止删除存档，请在浏览器设置中清除此站点数据。' } } }
function scrollToStart() { window.scrollTo({ top: 0, behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' }) }
function start() { try { game.value = createGame({ seed: seed.value.trim(), talents: [...chosen.value], attributes: { ...attributes.value } }); notice.value = ''; persist(); scrollToStart() } catch (error) { notice.value = error.message } }
async function act(index) { try { game.value = advance(toRaw(game.value), index); persist(); await nextTick(); eventHeading.value?.focus() } catch (error) { notice.value = error.message } }
function resume() { try { game.value = restoreGame(JSON.parse(localStorage.getItem(STORAGE))); remember.value = true; notice.value = '' } catch (error) { notice.value = error.message } }
function clearSave() { if (!window.confirm('清除这台设备上的游戏存档？当前页面的游戏仍可继续。')) return; remember.value = false; changeRemember(); notice.value = '本机存档已清除，当前游戏不会上传。' }
function restart() { if (!game.value?.ending && !window.confirm('重新开始会结束当前这局。确认继续？')) return; game.value = null; notice.value = ''; scrollToStart() }
function choiceHint(item) { const needs = Object.entries(item.need || {}).map(([id, value]) => `${[...ATTRIBUTES, ...STATS].find(s => s.id === id)?.name}≥${value}`); return `${item.risk ? '有意外风险' : '稳妥行动'}${needs.length ? ` · 需要${needs.join('、')}` : ''}` }
function changeText(changes) { return Object.entries(changes).map(([id, value]) => `${STATS.find(s => s.id === id)?.name}${value > 0 ? '+' : ''}${value}`).join(' / ') }
function download() { const url = URL.createObjectURL(new Blob([gameMarkdown(game.value)], { type: 'text/markdown;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = '末世模拟器-生存记录.md'; document.body.appendChild(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
</script>
<style scoped>
