d #3a4a42;border-radius:8px;padding:15px;display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px}.attribute-grid h3{margin:0;font-size:14px}.attribute-grid p{font-size:10px;color:#8f9f94;margin-bottom:0;line-height:1.7}.attribute-controls{display:flex;align-items:center;gap:12px}.attribute-controls button{width:30px;height:30px;border:1px solid #45594c;border-radius:4px;background:#24332a;color:#d2dfc6;cursor:pointer}.seed-field{display:block;font-size:13px;color:#becbae;line-height:1.8;margin:26px 0}.seed-field input{margin-top:10px}.game-check{display:inline-flex;align-items:center;gap:10px;font-size:12px;color:#b2c3ad}.game-check input{width:17px;height:17px;min-height:17px;accent-color:#b6cf91}.game-primary,.game-secondary{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:12px 19px;border-radius:5px;font-size:13px;cursor:pointer;margin:12px 10px 0 0}.game-primary{background:#bbce97;color:#182716;font-weight:800}.game-secondary{background:#233028;color:#becdaf;border:1px solid #455743}.game-primary:disabled{opacity:.4}.game-status{display:grid;grid-template-columns:110px 1fr;gap:32px;padding:26px;background:#1a2524;border:1px solid #526052;border-radius:10px}.day-marker{font:12px monospace;color:#a0b390;display:flex;flex-direction:column;justify-content:center;gap:8px}.day-marker strong{font-size:58px;color:#d3dfbd}.game-stat-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.game-stat-grid article>div:first-child{display:flex;justify-content:space-between;font-size:12px;color:var(--stat-color);margin-bottom:12px}.stat-bar{height:4px;background:#35423b}.stat-bar span{display:block;height:100%;background:var(--stat-color);transition:width .2s}.game-checkpoints{display:flex;justify-content:space-between;margin:22px 0 32px;font:11px monospace;color:#73867c;border-bottom:1px solid #36473e;padding-bottom:15px}.game-checkpoints .reached{color:#d2d5a6}.game-body{display:grid;grid-template-columns:1.2fr .8fr;gap:22px}.game-event h2{font-size:30px;line-height:1.5;margin:24px 0}.game-event h2:focus{outline:none}.event-story{line-height:2.1;color:#b9c5b9;font-size:16px;min-height:100px}.event-choices{display:grid;gap:13px;margin:30px 0}.event-choices button{display:flex;align-items:center;gap:16px;padding:20px;text-align:left;background:#20332d;color:#d4e0cb;border:1px solid #4b6050;border-radius:8px;cursor:pointer}.event-choices button>div{flex:1}.event-choices button strong,.event-choices button small{display:block}.event-choices button strong{font-size:14px;line-height:1.7}.event-choices button small{font-size:10px;color:#8da28e;margin-top:7px}.choice-number{font:13px monospace;color:#91ac86}.journal-heading{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid #3d4f45;padding-bottom:20px}.journal-heading h2{font-size:18px;margin:0}.journal-heading>span{font:11px monospace;color:#8d9e92}.game-journal ol{list-style:none;max-height:520px;overflow:auto;padding:0;margin:0}.game-journal li{border-bottom:1px solid #34453c;padding:22px 0}.game-journal li>span{font:10px monospace;color:#99ad90}.game-journal h3{font-size:14px;margin:10px 0}.game-journal p{font-size:12px;color:#a9b9a8;line-height:1.8}.game-journal small{font-size:10px;color:#8ba08c;line-height:1.9}.game-session{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:16px;margin-top:22px;font:11px monospace;color:#8fa38d;overflow-wrap:anywhere}.game-session>div{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.game-session button{margin:0}.game-notice{padding:15px;background:#344233;border:1px solid #5b7453;border-radius:8px;color:#c8d9b7;font-size:13px;line-height:1.8}@media(max-width:900px){.wasteland-setup,.game-body{grid-template-columns:1fr;gap:20px}.game-status{gap:20px}.game-journal ol{max-height:300px}}@media(max-width:540px){.wasteland-page{width:calc(100% - 28px);padding-top:30px}.setup-intro,.setup-form,.game-event,.game-journal{padding:22px}.talent-grid,.attribute-grid{grid-template-columns:1fr}.game-status{grid-template-columns:1fr;padding:20px}.day-marker{flex-direction:row;align-items:center}.day-marker strong{font-size:44px}.game-stat-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.game-event h2{font-size:25px}.event-story{font-size:14px}.event-choices button{padding:16px;gap:12px}.wasteland-heading h1 span{letter-spacing:.22em}}
